function Profile() {
  const name = 'Ayu';
  const role = 'React Developer';
  return (
    <div style={{ border: '1px solid #ddd', borderRadius: 12, padding: '1.5rem', maxWidth: 320 }}>
      <h1>Hello, {name}!</h1>
      <p>Role: {role}</p>
      <p>2 + 3 = {2 + 3}</p>
      <p>{name.length} characters in name</p>
    </div>
  );
}

export default function App() {
  return <Profile />;
}
